import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { createPublicClient, http, encodeDeployData, encodeAbiParameters, keccak256, toHex, getContractAddress } from 'viem';
import { baseSepolia } from 'viem/chains';

// Read-only: no wallet client, signing, broadcast, source purchase or credential file is used.
const rpcUrl = process.env.BASE_SEPOLIA_RPC_URL || 'https://sepolia.base.org';
const client = createPublicClient({chain:baseSepolia,transport:http(rpcUrl,{timeout:20000,retryCount:2})});
const expectedFactory='0x55f8b95e4ab02550b9758e23187fc366b91f910e';
const expectedVerifier='0xa4d6e5D0596f064290d810C1623D3C2114a55624';
const expectedAirnode='0x7B02Fd3324D2dC362f65a9c01e59EC5fDb4E1CCB';
const deployment=JSON.parse(readFileSync('evidence/v2/deployment.json','utf8'));
const isolation=JSON.parse(readFileSync('evidence/v2/isolated-wallets.json','utf8'));
const loadArtifact=name=>JSON.parse(readFileSync(`out/PostAndPaidConsentFactory.sol/${name}.json`,'utf8'));
const factoryArtifact=loadArtifact('PostAndPaidConsentFactory');
const verifierArtifact=loadArtifact('PostAndPaidIntakeVerifier');
const checks=[];
function check(name,passed,detail){checks.push({name,passed:!!passed,...(detail===undefined?{}:{detail})});}
const same=(a,b)=>typeof a==='string'&&typeof b==='string'&&a.toLowerCase()===b.toLowerCase();
check('deployment file factory address matches requested target',same(deployment.factory.address,expectedFactory));
check('deployment file verifier address matches requested target',same(deployment.factory.verifier,expectedVerifier));
check('deployment file signer matches pinned expected signer',same(deployment.airnode,expectedAirnode));
const [chainId,blockNumber]=await Promise.all([client.getChainId(),client.getBlockNumber()]);
check('RPC is Base Sepolia chain84532',chainId===84532);
const read=(address,abi,functionName)=>client.readContract({address,abi,functionName,blockNumber});
const [tx,receipt,factoryCode,verifierCode,airnode,verifier,verifierAirnode,domain,declaredChain,typeHash,block,balance]=await Promise.all([
 client.getTransaction({hash:deployment.factory.transactionHash}),
 client.getTransactionReceipt({hash:deployment.factory.transactionHash}),
 client.getCode({address:expectedFactory,blockNumber}),client.getCode({address:expectedVerifier,blockNumber}),
 read(expectedFactory,factoryArtifact.abi,'airnode'),read(expectedFactory,factoryArtifact.abi,'intakeVerifier'),
 read(expectedVerifier,verifierArtifact.abi,'airnode'),read(expectedFactory,factoryArtifact.abi,'domainSeparator'),
 read(expectedFactory,factoryArtifact.abi,'CHAIN_ID'),read(expectedFactory,factoryArtifact.abi,'CONSENT_TYPEHASH'),
 client.getBlock({blockNumber}),client.getBalance({address:expectedFactory,blockNumber})
]);
check('factory deployment receipt succeeded',receipt.status==='success');
check('deployment transaction is contract creation',tx.to===null);
check('receipt created the requested factory',same(receipt.contractAddress,expectedFactory));
check('deployment used isolated V2 executor',same(tx.from,isolation.executor),{sender:tx.from,expectedExecutor:isolation.executor});
check('V2 executor differs from V1 preparation source',!same(tx.from,isolation.source));
check('deployment carried zero creator collateral',tx.value===0n);
const expectedInput=encodeDeployData({abi:factoryArtifact.abi,bytecode:factoryArtifact.bytecode.object,args:[expectedAirnode]});
check('factory initcode and constructor argument match exactly',same(tx.input,expectedInput),{actualBytes:(tx.input.length-2)/2,expectedBytes:(expectedInput.length-2)/2,actualHash:keccak256(tx.input),expectedHash:keccak256(expectedInput)});
check('factory pins the expected Airnode',same(airnode,expectedAirnode));
check('factory pins the expected verifier',same(verifier,expectedVerifier));
check('verifier pins the same expected Airnode',same(verifierAirnode,expectedAirnode));
check('verifier is factory first CREATE child',same(getContractAddress({from:expectedFactory,nonce:1n}),expectedVerifier));
check('factory chain constant is84532',declaredChain===84532n);
const expectedDomain=keccak256(encodeAbiParameters(
 [{type:'bytes32'},{type:'bytes32'},{type:'bytes32'},{type:'uint256'},{type:'address'}],
 [keccak256(toHex('EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)')),keccak256(toHex('Post and Paid')),keccak256(toHex('2')),84532n,expectedFactory]
));
check('EIP712 domain binds name/version/chain/factory',same(domain,expectedDomain),{actual:domain,expected:expectedDomain,name:'Post and Paid',version:'2',chainId:84532,verifyingContract:expectedFactory});
const creatorType='CreatorConsent(bytes32 agreementId,address brand,address creator,string authorId,string postId,bytes32 nonce,address asset,uint256 feeWei,string requiredText,uint64 postedAfter,uint64 postedBefore,uint64 claimDeadline,uint64 consentDeadline,uint64 maxResponseAge)';
check('all fourteen signed terms match expected type hash',same(typeHash,keccak256(toHex(creatorType))),{actual:typeHash,expected:keccak256(toHex(creatorType)),type:creatorType});
function verifyRuntime(name,artifact,actualHex,expectedRoles){
 if(!actualHex||actualHex==='0x'){check(`${name} has deployed runtime`,false);return {present:false};}
 const actual=Buffer.from(actualHex.slice(2),'hex'),patched=Buffer.from(artifact.deployedBytecode.object.slice(2),'hex');
 check(`${name} runtime length matches compiled artifact`,actual.length===patched.length,{actualBytes:actual.length,compiledBytes:patched.length});
 const expectedWords=Object.fromEntries(Object.entries(expectedRoles).map(([role,address])=>[role,address.slice(2).toLowerCase().padStart(64,'0')]));
 const observations=[];const seenRoles=new Set();
 for(const [id,refs] of Object.entries(artifact.deployedBytecode.immutableReferences||{})){
  const values=refs.map(ref=>actual.subarray(ref.start,ref.start+ref.length).toString('hex'));
  const role=Object.keys(expectedWords).find(k=>expectedWords[k]===values[0]);
  const consistent=values.every(value=>value===values[0]);
  check(`${name} immutable ${id} matches pinned address`,!!role&&consistent&&refs.every(ref=>ref.length===32),{role:role||'unexpected',value:'0x'+values[0],locations:refs});
  if(role){seenRoles.add(role);for(const ref of refs)Buffer.from(expectedWords[role],'hex').copy(patched,ref.start);}
  observations.push({astId:id,role:role||'unexpected',value:'0x'+values[0],locations:refs});
 }
 check(`${name} contains every expected immutable role`,Object.keys(expectedRoles).every(role=>seenRoles.has(role)));
 const exact=patched.equals(actual);
 check(`${name} full runtime matches compiled code with verified immutables`,exact,{actualHash:keccak256(actualHex),expectedPatchedHash:keccak256(toHex(patched))});
 return {address:name==='factory'?expectedFactory:expectedVerifier,runtimeBytes:actual.length,actualRuntimeHash:keccak256(actualHex),compiledPatchedRuntimeHash:keccak256(toHex(patched)),immutableObservations:observations,exactRuntimeMatch:exact};
}
const factoryRuntime=verifyRuntime('factory',factoryArtifact,factoryCode,{airnode:expectedAirnode,intakeVerifier:expectedVerifier});
const verifierRuntime=verifyRuntime('verifier',verifierArtifact,verifierCode,{airnode:expectedAirnode});
const report={
 checkedAt:new Date().toISOString(),network:{name:'Base Sepolia',chainId,blockNumber:String(blockNumber),blockTimestamp:String(block.timestamp),blockHash:block.hash},
 readOnly:true,noWalletFilesOrSigningClientsUsed:true,transactionsSubmitted:0,paidApiCalls:0,
 deployment:{transactionHash:tx.hash,blockNumber:String(receipt.blockNumber),blockHash:receipt.blockHash,status:receipt.status,from:tx.from,nonce:tx.nonce,contractAddress:receipt.contractAddress,valueWei:String(tx.value),gasUsed:String(receipt.gasUsed)},
 factory:factoryRuntime,verifier:verifierRuntime,expectedSigner:expectedAirnode,observedFactoryBalanceWei:String(balance),
 compiler:{version:factoryArtifact.metadata.compiler.version,evmVersion:factoryArtifact.metadata.settings.evmVersion,optimizer:factoryArtifact.metadata.settings.optimizer},
 passed:checks.every(x=>x.passed),checks,
 creatorPilot:'PENDING — this deployment verification does not establish a new creator post, funded agreement or payout.',
 contractTiming:{basis:'Source analysis of unchanged V1 child embedded by the verified factory, not a new live creator-pilot transaction.',source:'contracts/PostAndPaidEscrow.sol',condition:'timestamp >= fundedAt',sameSecondIntakeReusePossible:true,strictNewEnvelopeEnforcedOnChain:false,applicationPolicy:'The executor deliberately buys another snapshot after funding; that is an application policy and separately recorded API purchase, not proof that a same-second intake envelope is unusable.'},
 reproduction:{
  method:'Recompile the repository with forge build, then compare the exact CREATE input and runtime code. Patch only compiler-declared immutable reference words to the pinned addresses, check every occurrence, and require exact equality of the entire resulting runtime. Read expected signer/verifier and EIP712 domain/type hashes from the deployed contracts at one fixed RPC block.',
  steps:['Run from the repository root: npm ci && forge build','Extract this JSON reproduction.source to .local/v2/verify-deployment.mjs using a filesystem write','node .local/v2/verify-deployment.mjs'],
  source:readFileSync(fileURLToPath(import.meta.url),'utf8')
 }
};
writeFileSync('evidence/v2/deployment-verification.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({passed:report.passed,checks:checks.length,failed:checks.filter(x=>!x.passed),chainId,blockNumber:String(blockNumber),factoryHash:factoryRuntime.actualRuntimeHash,verifierHash:verifierRuntime.actualRuntimeHash},null,2));
if(!report.passed)process.exitCode=1;
